func namedChildren(node *sitter.Node) []*sitter.Node {
	if node == nil {
		return nil
	}
	children := make([]*sitter.Node, 0, node.NamedChildCount())
	for index := range node.NamedChildCount() {
		children = append(children, node.NamedChild(index))
	}
	return children
}
