func namedChildOfKind(node *sitter.Node, kinds ...string) *sitter.Node {
	if node == nil {
		return nil
	}
	for _, child := range namedChildren(node) {
		if slices.Contains(kinds, child.Kind()) {
			return child
		}
	}
	return nil
}
